pub const DEFAULT_REVIEW_MS: f64 = 1209600000.0;

pub const MAX_REVIEW_MS: f64 = 7776000000.0;

/// Shortest and longest time a review stays open.
pub const MIN_REVIEW_MS: f64 = 86400000.0;

/// Team membership reviews: an administrator opens a review of a team's manual members, the team's maintainers (or
/// those of a team above it, or administrators) decide `keep` or `remove` for each person, and completing the
/// review removes everyone decided `remove` and, by the review's `onUndecided` rule, those nobody decided on.
/// Members team sync manages are not reviewed (their source group is). A review past its `dueAt` is completed by
/// the scheduler job `closeOverdueTeamReviews`.
pub static TEAM_REVIEW_COLLECTIONS: std::sync::LazyLock<Value> =
    std::sync::LazyLock::new(|| json!({"reviews":"teamReviews","items":"teamReviewItems"}));
